CREATE VIEW mart_recommendation_context_v1 AS WITH entitlement_summary AS (SELECT fe.GameKey, max(CASE  WHEN ((fe.OwnedGameCount > 0)) THEN (1) ELSE 0 END) AS owned_flag, max(CASE  WHEN ((das.AccessStatusName = 'Available')) THEN (1) ELSE 0 END) AS available_flag, max(CASE  WHEN ((das.AccessStatusName = 'Removed')) THEN (1) ELSE 0 END) AS removed_flag, max(CASE  WHEN ((das.AccessStatusName = 'Unknown')) THEN (1) ELSE 0 END) AS unknown_access_flag FROM FactGameEntitlement AS fe INNER JOIN DimAccessStatus AS das ON ((das.AccessStatusKey = fe.AccessStatusKey)) GROUP BY fe.GameKey)SELECT r.GameKey, r.GameID, r.GameTitle, r.PlayStatusName, COALESCE(es.owned_flag, 0) AS owned_flag, COALESCE(es.available_flag, 0) AS available_flag, COALESCE(es.removed_flag, 0) AS removed_flag, COALESCE(es.unknown_access_flag, 0) AS unknown_access_flag, r.final_recommendation_score, r.recommendation_status, r.playability_status, r.affinity_path, CASE  WHEN (((COALESCE(es.removed_flag, 0) = 1) AND (COALESCE(es.available_flag, 0) = 0))) THEN ('Unavailable') WHEN (((COALESCE(es.owned_flag, 0) = 1) AND (COALESCE(es.available_flag, 0) = 1) AND (r.PlayStatusName = 'In Progress'))) THEN ('Currently Playing') WHEN (((COALESCE(es.owned_flag, 0) = 1) AND (COALESCE(es.available_flag, 0) = 1) AND (r.PlayStatusName = 'Unplayed'))) THEN ('Playable Backlog') WHEN (((COALESCE(es.owned_flag, 0) = 1) AND (COALESCE(es.available_flag, 0) = 1) AND (r.PlayStatusName = 'Completed'))) THEN ('Completed') WHEN (((COALESCE(es.owned_flag, 0) = 1) AND (COALESCE(es.available_flag, 0) = 1) AND (r.PlayStatusName = 'Unknown'))) THEN ('Owned / Play Status Unknown') WHEN (((COALESCE(es.owned_flag, 0) = 0) AND (COALESCE(es.available_flag, 0) = 0) AND (COALESCE(es.unknown_access_flag, 0) = 1))) THEN ('Discovery Candidate') ELSE 'Access Unknown' END AS recommendation_context FROM mart_recommendation_final_v1 AS r LEFT JOIN entitlement_summary AS es ON ((es.GameKey = r.GameKey));
